        "raw": "物価高騰対応重点支援給付金\n（住民税均等割非課税世帯）\n【物価高騰対策給付金】\n\n①物価高が続く中で低所得世帯への支援を行うことで、低所得の方々の生活を維持する。\n②低所得世帯への給付金及び事務費\n③R５,R６の累計給付金額\nR５年度分の住民税非課税世帯 796世帯×70千円\n④R５年度分の住民税非課税世帯 （796世帯）\n\n物価高騰対応重点支援給付金\n（住民税均等割非課税世帯等）",
