        "note": "令和3年度の当該個票成果欄で実施を確認した独立名称。計画だけの催し・中止したスポーツ大会は含めず、既存グローバル人材育成事業に内包される英会話活動を別件にしない。数値は未抽出。",
        "context": "重点項目\n\n子育て・家庭教育支援の充実\n家庭教育支援チームによる子育てや家庭教育の支援、親育ち応援学習プログ\n\n目 的\n\nラムの普及や指導者養成、プレーパークによる親の集いの場づくり等を一体\n的に行い、家庭教育支援の総合的な体制づくりを行う。\n・家庭教育支援チーム「すくすくハート」による子育てや家庭教育の情報提\n供や相談等を実施する。\n\n計 画\n\n・親育ち応援学習プログラム実施とファシリテーターの養成を行い、地域人\n材による親同士の学びの場づくりを支援する。\n・プレーパークを定期的に開催し、保護者の集いの場づくりや仲間づくりを\n行い、家庭教育支援のプラットホームとする。\n〇家庭教育支援チーム「すくすくハート」の定例会を行い、様々な機関と連\n携・協働しながら、より効果的に取り組むことができた。\n〇地域住民や青少年ボランティアによるプレーパークを毎月開催し、保護者\n\n成 果\n\nや子どもの集いの場となった。また、家庭教育支援チーム員による子育て\n相談も行い、地域で子育て支援を行う仕組みづくりがスタートできた。\n○保幼小中の保護者を対象に、親育ち応援学習プログラムを実施し、保護者\n同士による学び合いの場を実現した。\n・家庭教育支援チーム「すくすくハート」の活動を充実させるとともに、チ\n\n今後の\n方向性\n\nームを中心に、子育てや家庭教育支援を行う体制を整備する。\n・就学前の家庭に必要な支援が届くように、関連機関と連携して必要な支援\n行う仕組みづくりに取り組む。\n\n20\n\n\n",
