        "start": 18798,
        "note": "令和3年度の当該個票成果欄で実施を確認した独立名称。計画だけの催し・中止したスポーツ大会は含めず、既存グローバル人材育成事業に内包される英会話活動を別件にしない。数値は未抽出。",
        "context": "重点項目\n目 的\n\n社会教育施設の充実\n施設の設備を行い、利用しやすい環境づくりを目指す。\n・西コミュニティセンターの集会室畳替え。\n\n計 画\n\n・戸川家記念館駐車場の整備と展示スペースの拡張。\n・町民総合会館の指定管理制度導入に関する検討と施設管理\n○西コミュニティセンターの集会室畳替えは、床下の損傷も伴っており工事費\nが増加したが整備は完了し、利用者に喜ばれている。\n○民具館倉庫を解体し、戸川家記念館の駐車スペースとして活用し、併せて記\n\n成 果\n\n念館２階に民具の展示スペースを整備した。\n〇町民総合会館に指定管理者制度を導入することが数年前から検討されてい\nたが、実務に着手できていなかった。本年度は導入によるメリットやデメリ\nットについて検証し制度設計や市場調査を行った。\n\n今後の\n\n・西コミュニティセンターの西和室空調機取替工事。\n\n21\n\n\n方向性\n\n・いかしの舎火災報知器の取替工事。\n・町民総合会館の指定管理制度導入に関する検討とアトリウムラウンジトッ\nプガラス交換工事、２階トイレ衛生化工事。\n・今後も各施設の点検等を行い、計画的に老朽化している施設や設備等の修繕\nや更新による整備を進めていく。\n\n",
        "contextStart": 18751
