        "context": "重点項目\n目 的\n\n地域ぐるみによる教育体制の充実\n学習支援や体験活動を中心とした「はやしま学」を通して、地域ぐるみの教\n育体制を築きながら、郷土愛を深め、社会貢献意識を高める。\n・\n「子どもカレッジ体験事業」として大学で学ぶ英会話体験や専門家が指導す\nる科学教室を開設し、子どもたちの学ぶ意欲や知的好奇心などを高める。\n・長期休業中に「わくわくサマーホリデー」や「わくわく算数教室」などを\n実施し、様々な体験活動によって視野を広げる。\n\n計 画\n\n・数学検定・漢字検定・英語検定３級以上の取得を目指す支援体制を作る。\n・放課後・土曜日・長期休業日を利用し、はやしま塾、英会話塾、夏休みわ\nくわくタイム等の事業を行い、補充学習や発展学習、体験学習などの充実\nを図る。\n・地域の方や教職員等がスタッフ・講師として参加するなど、地域ぐるみで\n子どもを育てる教育体制の構築を目指す。\n○長期休業中に「わくわくサマータイム」などを実施することができた。\n○検定試験の実施を行い多くの参加者が検定試験に挑戦した。\n\n成 果\n\n○放課後・土曜日・長期休業日を利用し、はやしま塾、英会話塾、夏休みわ\nくわくサマータイム等の事業を行い、補充学習や発展学習、体験学習を充\n実させることができた。\n・今後も学習支援や体験活動を企画実施し、子どもたちの学ぶ意欲や知的好奇\n\n今後の\n方向性\n\n心を高める事業を展開していく。\n・放課後や長期休業を活用した補充学習や発展学習事業を工夫して教育効果\nを高め実施していく。\n\n",
