        "context": "社会教育施設の充実\n重点項目\n\n社会教育施設の充実\n\n目 的\n\n施設の設備を行い、利用しやすい環境づくりを目指す。\n・西コミュニティセンターのトイレの洋式化を行う。\n・老朽化して汚れた公民館１階のカーペットの張替を行い、過ごしやすい公民\n\n計 画\n\n館とする。\n・良質な音楽をゆるびの舎から発信するために、１９９７年製で約２２年が経\n過して各部の消耗が激しく見受けられるため、スタインウエイピアノのオー\nバーホールを行う。\n○西コミュニティセンターのトイレの洋式化や中央公民館１階のカーペット\nの張替え等の施設整備は完了し、利用しやすい環境整備が図れた。\n\n成 果\n\n○ゆるびの舎のスタインウェイピアノのオーバーホールが完了し、生まれ変わ\nった文化ホールの「顔」ともいわれるグランドピアノを今後も永く愛用し活\n用していきたい。\n・西コミュニティセンターの集会室の畳替えを来年度実施する。\n\n今後の\n方向性\n\n・今後も点検等を行い、計画的に老朽化している施設や設備等の修繕や更新に\nよる整備を進めていく。\n・来年度には、スタインウェイピアノを使用した公演を予定している。\n\n",
