        "context": "５ 地域ぐるみによる教育体制の充実\n重点項目\n目 的\n\n地域ぐるみによる教育体制の充実\n学習支援や体験活動を中心とした「はやしま学」を通して、地域ぐるみの教\n育体制を築きながら、郷土愛を深め、社会貢献意識を高める。\n・\n「子どもカレッジ体験事業」として大学で学ぶ英会話体験や専門家が指導す\nる科学教室等へ子どもたちを参加させることによりより高度な学びを体験\nさせることにより、子どもたちの学ぶ意欲や知的好奇心などを高める。\n・長期休業中に小学生に、「わくわくサマーホリデー」や「わくわく算数教\n室」\n「料理教室」などを実施し、様々な体験活動によって視野を広げる。\n\n計 画\n\n・数学検定・漢字検定・英語検定３級以上の取得を目指し、支援体制を作\nる。\n・土曜日・放課後・長期休業日を利用し、はやしま学、ロゲイニング、英会\n話塾、夏休みわくわくタイム等の事業を行い、補充学習や発展学習、体験\n学習など魅力ある講座の充実を図る。\n・地域の方や教職員等がスタッフ・講師として参加するなど、地域ぐるみで\n子どもを育てる教育体制の構築を目指す。\n○長期休業中の「わくわくサマーホリデー」では、約１３０名の児童が参加\nし、地域の歴史や自然、ＳＤＧｓ等について楽しく学ぶ１０日間の体験を\n\n21\n\n\n通し、郷土愛を深めるとともに、これからの社会での自身の役割等を考え\nることができた。\n○小学生が提案・企画した「不老のみちロゲイニングラリー」を実現したこ\n成 果\n\nとで、郷土愛が深まり、社会貢献意識も高まった。３１チーム、１１４名\nと、子どもから大人まで多数の参加があり、大変好評だった。\n○早島っ子サポートボランティア制度により、多くの地域の方が土曜日・放\n課後・長期休業中の事業にボランティアとして参画し、地域ぐるみで子ど\nもを育てる教育体制の構築が進み、登録者５０名となった。\n・ロゲイニングに様々な教科の要素を組み合わせた「教科ロゲイニング」を実\n施し、身近な学習の楽しみに触れる機会を設ける。さらに、町内外の大人か\n\n今後の\n\nら子どもまで広く参加をつのり、早島の魅力をより幅広い層に伝えていく。\n\n方向性\n\n・コロナ禍で、「子どもカレッジ体験事業」ができていないため、社会情勢を\n考慮しながら実施していく。また、リモートでの交流や、人数を限定しての\n実施など、実施方法を工夫して教育効果を高めていく。\n\n",
