        "context": "６ ゆるびの舎での自主事業の充実\n重点項目\n目 的\n\nゆるびの舎での自主事業の充実\n町民の芸術・文化意識の向上を図るため、様々なジャンルの公演を鑑賞する機\n会の提供と気軽に参加できる場づくりを行う。\n・\n「吉田兄弟の三味線によるコンサート」を開催し、日本の伝統芸能に触れる\n機会を提供する。\n・\n“笑い”を通じて町民の「心の健康づくり」の推進を図ることを目的として\n\n計 画\n\n落語会を開催する。\n・様々なジャンルの提供を目的として、高校演劇を誘致する。\n・町民に日頃の練習の成果を発表する場を提供することを目的に、文化ホール\nスタインウエイピアノを開放し、ピアノリレーコンサートを開催する。\n○「吉田兄弟のコンサート」はコロナウイルス感染予防対策を徹底し、会場の\n人数制限を行い、２回公演で開催した。公演では、二人の原点である「三味\n線だけの世界」の迫力ある演奏で観客を魅了した。来場者からは「たくさん\nの音色が聞けて楽しいひと時だった」「二人の息の合った演奏に感動した」\n\n成 果\n\n「久しぶりに本物音楽を生で聴けて大変満足した」などの感想が寄せられ\n大好評であった。\n○感染予防対策を徹底し、令和の爆笑王こと四代目「三遊亭圓歌」、ゲストに\n人気落語家の「柳家喬太郎」らを迎え盛大に開催した。来場者からは「プロ\nの芸に感激した」などの意見が寄せられ、大いに笑い楽しみ四代目の襲名を\nお祝いし、本物の文化に触れることができた。\n\n22\n\n\n○２日間で１６０名のピアニストがピアノリレーコンサートに参加し日頃の\n練習の成果を発表することができた。感染症対策に万全を期して開催し、コ\nロナ禍で発表の場が少ない中、参加者から喜んでもらうことができた。\n・ゆるびの舎文化ホールの顔である「スタインウェイピアノ」がオーバーホー\nルを終え戻ってくるので、それを活かした事業を展開する。具体的には、町\n今後の\n\n民の方々に演奏していただく機会を提供できる「ピアノリレーコンサー\n\n方向性\n\nト」\n。また、高質なピアノの音色を鑑賞する機会を提供するため、プロによ\nるコンサートも計画する。\n・文化ホールで「早島シネマ」を毎月開催し、住民のニーズや稼働率を高める。\n\n",
