        "context": "地域への誇りと愛着の醸成\n自らが暮らす地域への愛着や誇りを育み、地域への問題意識を高め、住民自\n治に寄与する。\n地域をテーマとした講座、イベントを開催する。\n○「健康」「地方史」「ふるさと」をテーマに単位制の「まなびの舎」講座を実施\nし、１４コマ３５単位の講座に３１人が受講し、郷土の歴史や自然を再認識し\n\n成 果\n・\n課 題\n\nた。\n○小学生を対象にした「まち探検 ロゲイニング」を開催し、自分たちの知らな\nい町の姿を再発見した。\n○健康ウォーキングでは、昨年同様早島を１周するコースを設定し、多くの参\n加があり、地域を見直す契機となった。\n地域に焦点をあてた事業が実施でき、町民が自らの暮らす地域に関心をもつ\n\n今後の\n\n契機となった。今後も町の歴史、自然、環境など、町を知る様々なテーマを設\n\n方向性\n\n定し、町民としてのアイデンティティを高め、まちづくりに参加できるプログラム\nを提供していく必要がある。\n\n",
