        "context": "心と体の健康づくり\nだれもが健康で、生きがいをもち、安心して暮せるまちづくりのために、健康寿\n命の延長を図る。\n健康づくりプロジェクトの計画に則り、ラジオ体操、ウォーキングの普及に取り\n組むとともにトレーニングルームの活性化を図る。\n\n成 果\n・\n課 題\n\n○夏期休業中のラジオ体操会への参加者が増えるとともに、トレーニングルー\n\n今後の\n\n健康づくりという町の目標を共有し、その実現のために町民の参加しやすい、\n\n方向性\n\nまた参加したくなる活動の工夫をする必要がある。\n\nムの利用者も拡大した。\n\n16\n\n",
