        "note": "年度内の開催実績が明記された固有の学習・参加活動。平日/土曜の同一学習塾は一つの年次活動として扱い、英会話塾とEnjoy English Jukuは別名追加しない。既存親事業の子活動や講座回数の分割を除外。",
